<?php
require_once __DIR__ . '/../config/auth.php';require_admin(['Super Admin']);
$roles=['Super Admin','Admissions Officer','Content Manager'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'save');$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT)?:0;if($action==='delete'&&$id!==(int)$_SESSION['admin_id']){db()->prepare('UPDATE admins SET status="disabled" WHERE id=?')->execute([$id]);flash('success','Administrator access disabled.');}else{$name=trim((string)($_POST['full_name']??''));$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$role=(string)($_POST['role']??'');$password=(string)($_POST['password']??'');$status=in_array($_POST['status']??'active',['active','disabled'],true)?$_POST['status']:'active';if(!$email||mb_strlen($name)<3||!in_array($role,$roles,true)||(!$id&&strlen($password)<12)||($password!==''&&strlen($password)<12)){flash('error','Provide valid details. New or changed passwords need at least 12 characters.');}else{try{if($id){if($password!==''){db()->prepare('UPDATE admins SET full_name=?,email=?,role=?,status=?,password_hash=?,force_password_change=1 WHERE id=?')->execute([$name,$email,$role,$status,password_hash($password,PASSWORD_DEFAULT),$id]);}else{db()->prepare('UPDATE admins SET full_name=?,email=?,role=?,status=? WHERE id=?')->execute([$name,$email,$role,$status,$id]);}}else{db()->prepare('INSERT INTO admins (full_name,email,password_hash,role,status,force_password_change) VALUES (?,?,?,?,?,1)')->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$role,$status]);}flash('success','Administrator account saved.');}catch(PDOException){flash('error','Could not save. Check whether the email is already in use.');}}}redirect('admin/users.php');}
$editId=filter_input(INPUT_GET,'edit',FILTER_VALIDATE_INT)?:0;$editing=null;if($editId){$st=db()->prepare('SELECT id,full_name,email,role,status FROM admins WHERE id=?');$st->execute([$editId]);$editing=$st->fetch();}$admins=db()->query('SELECT id,full_name,email,role,status,last_login FROM admins ORDER BY id')->fetchAll();$pageTitle='Admin users';include __DIR__.'/../includes/header.php';
?><section class="admin-shell"><aside class="admin-sidebar"><a href="<?= e(url('admin/dashboard.php')) ?>">← Dashboard</a><a href="<?= e(url('admin/settings.php')) ?>">Settings</a></aside><div class="admin-content"><p class="eyebrow">Access control</p><h1>Administrator accounts</h1><?php include __DIR__.'/../includes/alerts.php';?><form class="form-panel" method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)($editing['id']??0) ?>"><div class="form-grid"><div class="field"><label>Name</label><input name="full_name" required value="<?= e($editing['full_name']??'') ?>"></div><div class="field"><label>Email</label><input name="email" type="email" required value="<?= e($editing['email']??'') ?>"></div><div class="field"><label>Role</label><select name="role"><?php foreach($roles as $role):?><option <?= ($editing['role']??'Content Manager')===$role?'selected':'' ?>><?= e($role) ?></option><?php endforeach;?></select></div><div class="field"><label>Password <?= $editing?'(leave blank to keep)':'(12+ characters)' ?></label><input name="password" type="password" <?= $editing?'':'required minlength="12"' ?> autocomplete="new-password"></div><?php if($editing):?><div class="field"><label>Status</label><select name="status"><option <?= $editing['status']==='active'?'selected':'' ?>>active</option><option <?= $editing['status']==='disabled'?'selected':'' ?>>disabled</option></select></div><?php endif;?></div><div class="form-actions"><button class="button">Save administrator</button></div></form><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($admins as $admin):?><tr><td><?= e($admin['full_name']) ?></td><td><?= e($admin['email']) ?></td><td><?= e($admin['role']) ?></td><td><?= e($admin['status']) ?></td><td><a class="text-link" href="<?= e(url('admin/users.php?edit='.$admin['id'])) ?>">Edit</a><?php if((int)$admin['id']!==(int)$_SESSION['admin_id']&&$admin['status']==='active'):?><form method="post" style="display:inline" data-confirm="Disable this administrator account?"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$admin['id'] ?>"><input type="hidden" name="action" value="delete"><button class="text-link">Disable</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></section><?php include __DIR__.'/../includes/footer.php';?>